import fs from'node:fs';import assert from'node:assert/strict';import{compactDefaultQueues}from'../nss114/compact-default-queues.mjs';import{connectRouter}from'../nss27/connect-router.mjs';import{encode,receipt}from'../nss11/v7-observe-repair/observe2/transport.mjs';
const r='work/morning-20261007/run-20261006234137-d2fdcbc7',cap=JSON.parse(fs.readFileSync('work/nss114/uplink-capacity-private.json')),pin=JSON.parse(fs.readFileSync('work/nss16/qos-capacity-private.json')),c=await connectRouter();
// jsonc historically emitted an empty MQ option table as []; tc emits {}.
// The original target validator treats only this proven-empty MQ table equally.
const shape=rows=>compactDefaultQueues(rows).map(q=>q.kind==='mq'?{...q,options:{}}:q);
try{const raw=await c.run('tc -j -s -d qdisc show dev wan; tc -j -s -d qdisc show dev lan4');fs.writeFileSync(r+'/physical-final-raw-private.json',JSON.stringify(raw,null,2)+'\n',{flag:'wx'});assert.equal(raw.code,0);const lines=raw.stdout.trim().split('\n');assert.equal(lines.length,2);const wan=compactDefaultQueues(JSON.parse(lines[0])),lan=compactDefaultQueues(JSON.parse(lines[1]));assert.deepEqual(shape(wan),shape(cap.defaultQueues));assert.deepEqual(shape(lan),shape(pin.interfaces.lan4.qdiscs));const e=encode("lua - <<'NSS115_FAILED_OWNER_READ'\n"+fs.readFileSync('work/nss114/failed-wan-owner.lua','utf8')+"\nNSS115_FAILED_OWNER_READ\n"),owner=receipt(await c.run(e.command),e);fs.writeFileSync(r+'/final-failed-wan-owner-private.json',JSON.stringify(owner,null,2)+'\n',{flag:'wx'});assert.equal(owner.code,0);const seal=JSON.parse(owner.stdout);const out={passed:true,observedAt:new Date().toISOString(),readonly:true,physicalWanOriginalMqFourFqCodelRestored:true,lan4OriginalMqFourFqCodelRestored:true,defaultQueueOptionsAndHandlesExact:true,failedWan4ProcessOwnerChecked:true,wan4Running:seal.running,wan4Lifecycle:seal.lifecycle??'not-running',wrapperSha256:seal.wrapperSha256};fs.writeFileSync(r+'/physical-final.json',JSON.stringify(out,null,2)+'\n',{flag:'wx'});console.log(JSON.stringify(out));}finally{c.close()}
